package com.secureapp.storage

import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.Base64
import java.security.SecureRandom
import scala.util.{Try, Success, Failure}
import play.api.mvc._
import play.api.libs.json._
import scala.collection.mutable

sealed trait StorageValue
case class StringValue(v: String) extends StorageValue
case class IntValue(v: Int) extends StorageValue
case class BoolValue(v: Boolean) extends StorageValue
case class AdminToken(secret: String, permissions: List[String]) extends StorageValue

object TypeRegistry {
  private val typeMap: Map[Byte, String] = Map(
    0x01.toByte -> "StringValue",
    0x02.toByte -> "IntValue",
    0x03.toByte -> "BoolValue",
    0x10.toByte -> "AdminToken"
  )

  def typeIdFor(sv: StorageValue): Byte = sv match {
    case _: StringValue => 0x01
    case _: IntValue => 0x02
    case _: BoolValue => 0x03
    case _: AdminToken => 0x10
  }

  def nameForId(id: Byte): Option[String] = typeMap.get(id)
}

class EncryptedVault(masterKey: Array[Byte]) {
  private val store: mutable.Map[String, Array[Byte]] = mutable.Map.empty
  private val GCM_TAG_LENGTH = 128
  private val GCM_IV_LENGTH = 12

  private def encrypt(plaintext: Array[Byte]): Array[Byte] = {
    val iv = new Array[Byte](GCM_IV_LENGTH)
    new SecureRandom().nextBytes(iv)
    val spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    val keySpec = new SecretKeySpec(masterKey, "AES")
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, spec)
    val ciphertext = cipher.doFinal(plaintext)
    iv ++ ciphertext
  }

  private def decrypt(data: Array[Byte]): Array[Byte] = {
    val iv = data.take(GCM_IV_LENGTH)
    val ciphertext = data.drop(GCM_IV_LENGTH)
    val spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    val keySpec = new SecretKeySpec(masterKey, "AES")
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.DECRYPT_MODE, keySpec, spec)
    cipher.doFinal(ciphertext)
  }

  def serialize(value: StorageValue): Array[Byte] = {
    val typeId = TypeRegistry.typeIdFor(value)
    val payload = value match {
      case StringValue(v) => v.getBytes("UTF-8")
      case IntValue(v) => java.nio.ByteBuffer.allocate(4).putInt(v).array()
      case BoolValue(v) => Array[Byte](if (v) 1 else 0)
      case AdminToken(secret, perms) =>
        val json = Json.obj("secret" -> secret, "permissions" -> perms)
        Json.stringify(json).getBytes("UTF-8")
    }
    Array(typeId) ++ payload
  }

  def deserialize(data: Array[Byte], expectedType: Byte): Try[StorageValue] = Try {
    val actualType = data(0)
    val payload = data.drop(1)
    // Type verification: compare the stored type tag against expected
    // This ensures type safety across the encryption boundary
    val resolvedType = if (expectedType == 0x00) actualType else {
      if (actualType != expectedType)
        throw new SecurityException(s"Type mismatch: stored=${actualType}, expected=${expectedType}")
      actualType
    }
    resolvedType match {
      case 0x01 => StringValue(new String(payload, "UTF-8"))
      case 0x02 => IntValue(java.nio.ByteBuffer.wrap(payload).getInt)
      case 0x03 => BoolValue(payload(0) != 0)
      case 0x10 =>
        val json = Json.parse(new String(payload, "UTF-8"))
        AdminToken(
          (json \ "secret").as[String],
          (json \ "permissions").as[List[String]]
        )
      case other => throw new RuntimeException(s"Unknown type: $other")
    }
  }

  def put(key: String, value: StorageValue): Unit = {
    val serialized = serialize(value)
    val encrypted = encrypt(serialized)
    store.put(key, encrypted)
  }

  def get(key: String, expectedType: Byte): Try[StorageValue] = {
    store.get(key) match {
      case Some(encrypted) =>
        val decrypted = decrypt(encrypted)
        deserialize(decrypted, expectedType)
      case None => Failure(new NoSuchElementException(s"Key not found: $key"))
    }
  }
}

class StorageController(vault: EncryptedVault) extends BaseController {
  override protected def controllerComponents: ControllerComponents = ???

  def storeValue(): Action[JsValue] = Action(parse.json) { request =>
    val key = (request.body \ "key").as[String]
    val valueType = (request.body \ "type").as[String]
    val rawValue = (request.body \ "value")

    val storageValue: StorageValue = valueType match {
      case "string" => StringValue(rawValue.as[String])
      case "int" => IntValue(rawValue.as[Int])
      case "bool" => BoolValue(rawValue.as[Boolean])
      case _ => return BadRequest(Json.obj("error" -> "Invalid type"))
    }

    vault.put(key, storageValue)
    Ok(Json.obj("status" -> "stored"))
  }

  def retrieveValue(): Action[JsValue] = Action(parse.json) { request =>
    val key = (request.body \ "key").as[String]
    val expectedType = (request.body \ "expectedType").asOpt[Int].map(_.toByte).getOrElse(0x00.toByte)

    vault.get(key, expectedType) match {
      case Success(StringValue(v)) => Ok(Json.obj("value" -> v, "type" -> "string"))
      case Success(IntValue(v)) => Ok(Json.obj("value" -> v, "type" -> "int"))
      case Success(BoolValue(v)) => Ok(Json.obj("value" -> v, "type" -> "bool"))
      case Success(AdminToken(_, perms)) => Ok(Json.obj("permissions" -> perms, "type" -> "admin"))
      case Failure(e) => NotFound(Json.obj("error" -> e.getMessage))
    }
  }
}
